// reproduce-unminified-bug.js
// Run this with `node reproduce-unminified-bug.js` in a project
// that has lighthouse-core installed (e.g. npm install lighthouse)

const UnminifiedJavascriptAudit = require('lighthouse-core/audits/byte-efficiency/unminified-javascript.js');
const KB = 1024;

// Construct a script that is actually minified, but has a license block
// with newlines/carriage-returns that will trip up Esprima.
const licenseHeader = [
  '/*!',
  ' * Copyright 2018 Example Corp.',
  ' * All rights reserved.',
  ' */'
].join('\r\n');

// Minified body
const minifiedBody = 'var a=1,b=2;console.log(a+b);';

const fakeScript = `${licenseHeader}\r\n${minifiedBody}`;

// Artifacts shape expected by the audit
const artifacts = {
  Scripts: {
    '1': fakeScript
  }
};

// Simulate a network record for a 100KB transfer
const networkRecords = [
  {
    requestId: '1',
    url: 'https://example.com/fake.js',
    transferSize: 100 * KB,
    resourceType: 'Script'
  }
];

// Invoke the audit
const auditResult = UnminifiedJavascriptAudit.audit_(artifacts, networkRecords);

// Output the result
console.log('Warnings:', auditResult.warnings);
console.log('Items flagged as unminified:', auditResult.items);
